style.css:
@-moz-document domain("roblox.com") {
html,
  body {
    min-height: 100% !important;
    background-color: #111 !important;
    background-image: url("https://i.pinimg.com/736x/68/73/35/687335174749d7435050583139e0943b.jpg") !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  body {
    margin: 0 !important;
  }

  #app,
  #app > div,
  #root,
  #root > div,
  main,
  [role="main"],
  #container-main,
  .container-main,
  #rbx-body,
  .rbx-body {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  body::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    z-index: -1 !important;
    pointer-events: none !important;
    background: url("https://i.pinimg.com/736x/68/73/35/687335174749d7435050583139e0943b.jpg")
      center center / cover fixed no-repeat !important;
  }
}
